mapper.select:
SELECT c.*, m.nick_name as nickName, m.profile_image_url as profileImageUrl, (SELECT COUNT(*) FROM TB_LIKE WHERE comment_idx = c.idx) as likeCount, (SELECT COUNT(*) FROM TB_UNLIKE WHERE comment_idx = c.idx) as unlikeCount, CASE WHEN EXISTS ( SELECT 1 FROM TB_LIKE WHERE comment_idx = c.idx AND member_idx = #{memberIdx} ) THEN true ELSE false END as isLiked, CASE WHEN EXISTS ( SELECT 1 FROM TB_UNLIKE WHERE comment_idx = c.idx AND member_idx = #{memberIdx} ) THEN true ELSE false END as isUnliked FROM TB_COMMENT c LEFT JOIN TB_MEMBER m ON c.member_idx = m.idx WHERE c.post_idx = #{postIdx}
AND c.parent_comment_idx IS NULL
ORDER BY c.created_at DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE TB_COMMENT
SET content = #{content}, updated_at = CURRENT_TIMESTAMP
WHERE idx = #{idx} AND member_idx = #{memberIdx}

mapper.delete:
DELETE FROM TB_COMMENT
WHERE idx = #{commentIdx}
AND member_idx = #{memberIdx}

mapper.select:
SELECT COUNT(*)
FROM TB_COMMENT
WHERE post_idx = #{postIdx}
